INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES
(61497, 0, 0, 'The Bracing of Nature huh? I remember the name Everwyl fondly. Please, let him know that I expect this returned when he is finished with it.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66627'),
(61561, 0, 0, 'A dark magic lingers, it is foul in intent...', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66612'),
(61512, 0, 0, 'Walk with the blessings of Cenarius, and may nature guide your path noble one.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66617'),
(61326, 0, 0, 'I invoke the Ancient Pact! Ysera, bless this mortal. Grant him access to the Emerald Dream!', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66608'),
(61545, 0, 0, 'You have done well so far, and the Green Dragonflight is already in your debt. Hereby, I grant you my blessing to enter our sacred realm.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66609'),
(61545, 1, 0, 'Stop the Awakening.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66610'),
(61326, 1, 0, 'I invoke the Ancient Pact! Dreamways, open before me.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 65014'),
(61326, 2, 0, 'Something is wrong…', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 65015'),
(61326, 3, 0, 'I invoke the Ancient Pact! Open the way to the Emerald Dream!', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 65016'),
(61326, 4, 0, 'These were the minions of Nightmare for sure. Oh, what is happening…', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 65017'),
(61326, 5, 0, 'Lady Ysera… ', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 65019'),
(61326, 6, 0, 'We are in need of your blessing, my lady. I’ve found a mortal soul willing to stop the Awakening.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 65021'),
(61326, 7, 0, 'Oh no…', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 65029'),
(61326, 8, 0, '%s stops his cast.', 16, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 65030'),
(61545, 2, 0, 'Who dares to open the Dreamways?', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 65018'),
(61545, 3, 0, 'Speak quickly, Ralathius. The Nightmare is advancing on our positions.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 65020'),
(61545, 4, 0, 'Not a moment too soon. Solnius already enclosed himself in the Emerald Sanctum. The Awakening is upon us.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 65022'),
(61545, 5, 0, 'Yet, I cannot grant my blessing to this mortal. It is too dangerous. The Dreamway in Hyjal can be destroyed at any moment.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 65023'),
(61545, 6, 0, 'Larannikus has fallen to the Nightmare. In this very moment, he is working to sever the connection of the Dream to the World Tree.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 65024'),
(61545, 7, 0, 'If this happens… The reflection of Nordrassil in the Dream would be vulnerable to attack, and the Dreamways would close, trapping those without the innate ability to Dreamwalk.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 65025'),
(61545, 8, 0, 'Larannikus must be slain before I grant my blessing.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 65026'),
(61545, 9, 0, 'Ralathius, my faithful servant. The fate of the Emerald Dream is in your hands.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 65028'),
(61546, 0, 0, 'Lady Ysera, they are approaching. We must go.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 65027');
INSERT INTO `npc_text` (`ID`, `text0_0`, `text0_1`, `Probability0`, `VerifiedBuild`) VALUES (9061497, 'What is it you have come to search for here beneath the World Tree? Knowledge, power?', 'What is it you have come to search for here beneath the World Tree? Knowledge, power?', 1, 0);
